-- Seeds 3 "workflow example" datasets - discoverable from A Workflow/
-- Something Else's free-text answer (see src/onboarding/entryIntents.jsx's
-- resolveWorkflowExample()) instead of always falling into the empty
-- Forms-template preview. Not tied to a fixed entry_intent (no demo_routes
-- row) - demo_datasets.keywords is what makes one of these discoverable.
-- Generated by scripts/generate-demo-seed.js.

alter table demo_datasets add column if not exists keywords text[];
alter table demo_datasets add column if not exists destination text default 'report'
  check (destination in ('form', 'records', 'report', 'dashboard', 'payroll'));

-- Inventory Tracking
values (
  '99999999-9999-4999-8999-999999999999',
  'Kola & Co Ventures Inventory',
  'A sample inventory tracker, used to power the onboarding demo.',
  'published', true, '7d91d04c-d223-4ef1-a94d-382aa2d31bfe',
  '{"reportDateField":"last_restocked","reportAmountField":"stock_value"}'::jsonb,
  '[{"id":"item_name","type":"text","label":"Item Name","required":true},{"id":"sku","type":"text","label":"SKU","required":false},{"id":"category","type":"dropdown","label":"Category","required":false,"options":["Raw Materials","Packaging","Finished Goods","Equipment","Other"]},{"id":"quantity_on_hand","type":"number","label":"Quantity on Hand","required":true},{"id":"reorder_level","type":"number","label":"Reorder Level","required":false},{"id":"unit_cost","type":"number","label":"Unit Cost","required":false},{"id":"stock_value","type":"number","label":"Stock Value","required":false},{"id":"supplier","type":"text","label":"Supplier","required":false},{"id":"last_restocked","type":"date","label":"Last Restocked","required":false},{"id":"notes","type":"longtext","label":"Notes","required":false}]'::jsonb
)
on conflict (id) do nothing;



